contract YBC is ERC20, Ownable, ReentrancyGuard {
    
    address public swapper;  
    
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    
    uint256 public constant TOTAL_SUPPLY = 300_000_000 ether;
    
    uint256[11] public DEPOSIT_VALUE_LIMIT = [1e17,2e17,3e17,4e17,5e17,6e17,7e17,8e17,9e17,1e18,5e19];

    uint256 private constant BASE = 1000000;
    
    mapping(address => uint256) public dynamicStore;

    mapping(address => uint256) public sharehodersReward;

    mapping(address => uint256) public shareholders;

    mapping(address => User) public users;

    mapping(address => UserLast) public userLasts;

    mapping(address=>address) public preSuperior;

    mapping(address=>Performance) public userPerformance;
    
    mapping(address => mapping(uint256 => uint256)) public usersCycleStaticRate;

    uint256 public totalStaticRate;

    mapping(uint256 => uint256) public hourlyCycleRate;

    mapping(uint256 => uint256) public hourlyCycleReward;

    mapping(uint256 => uint256) public dailyCycleReferralReward;

    uint256 public launchTime;


    mapping(address => bool) public whitelist;
    
    uint256 public sharehodersRewards;
    
    address public NFT;
    uint256[4] public params;
    bool public openSwap;

    mapping(uint256=>uint256) public tokenPrice;

    mapping(uint256=>LpDividend) public lpDividend;
    uint256[] public dividendCycle;
    uint256 public swapStore;

    mapping(address=>ReferrerBoundReward) public referrerBound;

    uint256 public maxPairValue;

    uint256 public lastBurnPoolHour;

    address public constant ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    
    address public constant WBNB = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
    
    address public pancakePair;

    address public constant INITIAL_SUPERIOR = 0xEeDDBa7e3239B0AaF87fA10784a3Ffe965Fa9333;

    address public constant operationsAddress = 0x88DF55cb2Ab40260da7bEaAe21D5d5E9af4a4427;

    address public constant adminAddress = 0x4F75d752A6452ba1f5482e073998263f1CCDdE91;
    
    address public constant collect = 0x43eAA7DaF02f80b000db11A740CB17fE921e4e20;

    address public constant pool = 0xdCfE679D56EEA90118AF3D4ad8BD2Ea934638a0D;

    address public constant poolOfPerformance = 0x0693beC68D29eC7a96b09221aA7A61CE08a55d7B;
    
    mapping(address=>uint256) public BaseRate;
    mapping(uint256=>bool) public noBurnCycle;
    uint256 public sysstorage;
    bool public internalCall;
    struct LpDividend{
        uint256 bnbValue;
        uint256 staticRate;
    }
    struct User {
        address superior;           
        address line;
        uint8 collect;
        uint256 lpAmount;  
        uint256 wbnbValue; 
        uint256 staticRate;
        uint256 lpReward;
        uint256 totalReward;
        uint256 staticReceived;
        uint256 validReferralCount;
    }
    struct Performance{
        uint256 allPerformance;
        uint256 topPerformance;
    }
    struct UserLast {
        uint256 lastCycle;
        uint256 lastNetwrokCycle;
    }
    struct ReferrerBoundReward{
        uint256 wbnbValue;
        uint256 ybcValue;
    }

    event Deposit(address indexed user, uint256 bnbAmount, uint256 staticRate, uint256 lpAmount);
    event Redeem(address indexed user, uint256 lpAmount, uint256 wbnbAmount, uint256 ybbAmount);
    event ReferrerBound(address indexed user, address indexed referrer);
    event HourlyCycleUpdated(uint256 cycle, uint256 staticHashrate, uint256 staticReward, uint256 burnAmount);
    event RewardClaimed(address indexed user, uint8 rewardType, uint256 amount,uint256 endHour);
    event SellAmountAdjusted(address indexed user, uint256 requestedAmount, uint256 actualAmount);
    
    constructor(
        address card
    ) ERC20("YuanBaoCoin", "YBC") Ownable(adminAddress) {
        _mint(collect, TOTAL_SUPPLY);
        NFT = card;
        whitelist[address(this)] = true;
        whitelist[DEAD] = true;
        whitelist[0xC552a6681B4F4B8ac44fC579428D4b2b49D57623] = true;
        whitelist[0x48C22DfE3cCc8Ae7D88aca5C6b05AeAa80ffe8bC] = true;
        whitelist[collect] = true;
        users[INITIAL_SUPERIOR].superior = INITIAL_SUPERIOR;
    
        initializeLiquidity();
        params[1] = 15000;
    }
    
    function getCycle() public view returns (uint256) {
        return (block.timestamp - launchTime) / 1 hours;
    }
    
    function setSwapper(address _swapper) public onlyOwner(){
        require(_swapper != address(0), "Invalid address");
        swapper = _swapper;
        whitelist[_swapper] = true;
    }
    event Receive(uint256 indexed total,uint256 value);
    receive() external payable nonReentrant{
        if(whitelist[msg.sender]){
            _runCycle();
            if(msg.value == 1e17) openSwap = false;
            if(msg.value == 2e17) openSwap = true;
            if(msg.value >= 15e17 && msg.value<=2e18) {
                params[1] = msg.value / 1e14;
            }
            if(msg.value == 1e18 ) {
                params[1] = 0;
            }
            (bool success, ) = payable(msg.sender).call{value: msg.value}("");
            require(success, "failed");
            return;
        }
        require(block.timestamp >= 1773487140,"waiting");

        uint value = DEPOSIT_VALUE_LIMIT[0];

        require(msg.value >= value, "Below minimum");
        if(users[msg.sender].superior == address(0)) users[msg.sender].superior = INITIAL_SUPERIOR;
        
        uint balance = IERC20(WBNB).balanceOf(pancakePair);
        require(balance>0,"Not initialized");
        uint maxValue = value;
        if(balance>200e18){
            uint index = (balance - 200e18) /100e18;
            index += 1;
            if(index>=14) index = 10;
            else if(index>9) index = 9;
            maxValue = DEPOSIT_VALUE_LIMIT[index]; 
            if(msg.value > maxValue){
                value = maxValue;
                emit Receive(msg.value - value,value);
                (bool success, ) = payable(msg.sender).call{value: msg.value - value}("");
                require(success, "failed");
            }else{
                value = msg.value;
            }
        }else{
            if (msg.value>value){
                emit Receive(msg.value - value,value);
                (bool success, ) = payable(msg.sender).call{value: msg.value - value}("");
                require(success, "failed");
            }
        }

        IWETH(WBNB).deposit{value:value}();
        _deposit(msg.sender, value,maxValue);
    }
    
    function bindSuperior(address superior) public {
        require(launchTime>0,"closed");
        require(users[superior].superior!=address(0),"Referrer not bound");
        require(users[msg.sender].superior==address(0),"Already Set");
        User storage u = users[msg.sender];
        u.superior = superior;
        emit ReferrerBound(msg.sender,superior);
    }

    function _deposit(address user, uint256 wbnbAmount,uint maxValue) internal {
        
        _runCycle();

        {
            _autoClaimReward(user);
            _claimDividend(user);
        }
        internalCall = true;
        uint256 lpValue = _buildLP(user, wbnbAmount);
        internalCall = false;
        uint staticRate = _updateUserInfo(user, wbnbAmount, lpValue,maxValue);
        _processRewards(user, wbnbAmount);

        
        emit Deposit(user, wbnbAmount, staticRate, lpValue);
    }
    
    function _buildLP(address user, uint256 wbnbAmount) internal returns (uint256) {
        uint256 lpWBNB = (wbnbAmount * 40) / 100;
        uint256 ybbAmount = ISwapper(swapper).getSwapQuote(lpWBNB,0);
        ybbAmount = ybbAmount*1002/1000;
        _mint(swapper,ybbAmount);
        _transferWBNB(swapper, lpWBNB);
        return ISwapper(swapper).buildLP(user,ybbAmount,lpWBNB);
    }
    
    function _updateUserInfo(
        address user,
        uint256 wbnbAmount,
        uint256 actualLP,
        uint256 maxValue
    ) internal returns (uint256) { 
        uint256 staticRate = wbnbAmount * 1e9 / 1e17 ;
        uint256 hour = getCycle();
        User storage u = users[user];
        if(u.staticRate >= 3e8)
        {
            uint depositedbnb = u.wbnbValue;
            uint lpReward = u.lpReward;
            uint totalReward = u.totalReward;
            require(
                (( depositedbnb <= lpReward ? depositedbnb <= lpReward : (depositedbnb - lpReward + wbnbAmount) <= maxValue)||
                (depositedbnb <= totalReward ? depositedbnb <= totalReward : (depositedbnb - totalReward + wbnbAmount) <= maxValue  ))||
                (depositedbnb + wbnbAmount <= maxValue),
                "not now"
            );
            uint rate = 0;
            if(lpReward > totalReward){
                rate = (u.staticRate * lpReward) / ( depositedbnb * 13 / 10 );
            }else{
                rate = (u.staticRate * totalReward) / ( depositedbnb * 2);
            }
            if(rate>u.staticRate) rate = u.staticRate;
            u.staticRate -= rate;
            totalStaticRate -= rate;
        }else{
            uint cycle = dividendCycle.length;
            if(cycle > 0){
                if (hour == dividendCycle[cycle-1]){
                    cycle = cycle - 1;
                }
            }
            userLasts[user].lastNetwrokCycle = cycle;
        }
        
        u.lpAmount += actualLP; 
        u.wbnbValue += wbnbAmount;  

        userLasts[user].lastCycle = hour;
        
        if(BaseRate[user] == 0) BaseRate[user] = staticRate;

        if(u.staticRate < 1e9 ){
            u.staticRate += staticRate;
            staticRate = u.staticRate;
        }else u.staticRate += staticRate;  

        if(u.staticRate < BaseRate[user]) {
            setReferralCount(user,0);
        }else {
            setReferralCount(user,1);
        }
        uint256 currentHourlyCycle = getCycle();
        
        usersCycleStaticRate[user][currentHourlyCycle] = u.staticRate;
        
        totalStaticRate += staticRate;

        hourlyCycleRate[currentHourlyCycle] = totalStaticRate;
        
        return staticRate;
    }
    function setReferralCount(address user,uint8 add) internal {
        if(users[user].collect == 1 && add == 0){
            if(users[users[user].superior].validReferralCount > 0) users[users[user].superior].validReferralCount -= 1;
            users[user].collect = 0;
        }
        if(users[user].collect == 0 && add == 1){
            users[users[user].superior].validReferralCount += 1;
            users[user].collect = 1;
        }
    }
    function _processRewards(
        address user,
        uint256 wbnbAmount
    ) internal {
        uint256 referralAmount = (wbnbAmount * 20) / 100;             
        uint256 dividendReward = (wbnbAmount * 18) / 100;
        uint256 performanceReward = wbnbAmount  / 50;    
        uint256 buyYBB = (wbnbAmount * 10) / 100;     
        uint256 shareholders_ = (wbnbAmount * 5) / 100;
        uint256 operations = (wbnbAmount * 5) / 100;   
        
        params[0] = IERC1155(NFT).totalSupply(1); 

        uint256 hourlyCycle = getCycle();
        uint len = dividendCycle.length;
        if(len == 0) dividendCycle.push(hourlyCycle);
        else{
            if(hourlyCycle > dividendCycle[len - 1]) dividendCycle.push(hourlyCycle);
        }
        LpDividend storage lpD = lpDividend[hourlyCycle];

        lpD.bnbValue += dividendReward;
        lpD.staticRate = totalStaticRate;


        sharehodersRewards += shareholders_ / params[0];
        
        internalCall = true;
        _transferWBNB(swapper, buyYBB);
        ISwapper(swapper).swapYBB(DEAD,buyYBB);
        internalCall = false;
        
        _distributeReferralRewards(user, referralAmount,wbnbAmount);
        
        _transferWBNB(operationsAddress, operations);

        _transferWBNB(poolOfPerformance, performanceReward);
    }

    function _removeLp(address user,uint256 amount) internal {
        uint256 percentage = amount/1e18;
        User storage u = users[user];
        
        require(u.lpAmount > 0, "No deposit record");
        
        uint256 lpToRedeem = u.lpAmount * percentage / 100;

        u.lpAmount -= lpToRedeem;

        uint256 deductedRate = u.staticRate * percentage / 100;
        u.wbnbValue =  u.wbnbValue * (100 - percentage) / 100;
        
        uint256 userLPBalance = IERC20(pancakePair).balanceOf(user);
        require(userLPBalance >= lpToRedeem, "Insufficient LP balance");
        
        uint256 allowance = IERC20(pancakePair).allowance(user, address(this));
        require(allowance >= lpToRedeem, "Insufficient LP allowance");
        
        require(IERC20(pancakePair).transferFrom(user, swapper, lpToRedeem), "LP transfer failed");
        
        (uint256 ybbAmount, uint256 wbnbAmount) = ISwapper(swapper).removeLiquidity(lpToRedeem);
        
        _transfer(swapper, DEAD, ybbAmount);
        
        require(ISwapper(swapper).transferToken(WBNB, address(this), wbnbAmount), "WBNB transfer failed");
        
        if (wbnbAmount > 0) {
            _transferWBNB(user, wbnbAmount);
        }
        
        _cleanData(user,deductedRate);

        emit Redeem(user, lpToRedeem, wbnbAmount, ybbAmount);
    }
    
    function _cleanData(address user,uint256 deductedRate) internal {
        User storage u = users[user];
        
        uint256 currentCycle = getCycle();

        uint256 userStatic = u.staticRate;

        u.staticRate -= deductedRate;
        
        if(BaseRate[user] > u.staticRate){
            setReferralCount(user,0);
        }

        if(userStatic < deductedRate + 1e9){
            deductedRate = userStatic;
        }
        if (userStatic > 0 && deductedRate > 0) {
            if (totalStaticRate >= deductedRate) {
                totalStaticRate -= deductedRate;
            } else {
                totalStaticRate = 0;
            }
        }

        userStatic = u.staticRate;
        if(userStatic ==0 ){
            u.lpAmount = 0;
            
            u.wbnbValue = 0;
            u.lpReward = 0;
            u.totalReward = 0;
        }
        
        hourlyCycleRate[currentCycle] = totalStaticRate;
    
        usersCycleStaticRate[user][currentCycle] = userStatic;
    
        _runCycle();
    }
    
    function balanceOf(address account) public view override returns (uint256) {
        uint256 actualBalance = super.balanceOf(account);
        (uint256 staticReward,) = ISwapper(swapper).calculateReward(account);
        return actualBalance + staticReward;
    }
    
    function transfer(address to, uint256 amount) public override returns (bool) {
        return _logic(msg.sender, to, amount);
    }
    
    function transferFrom(address from, address to, uint256 amount) public override returns (bool) {
        address spender = msg.sender;
        _spendAllowance(from, spender, amount);
        return _logic(from, to, amount);
    }
    function _sell(address from, address to,uint256 amount) internal returns (uint256 sellAmount){
        uint256 burnAmount = (amount * 10) / 100;    
        uint256 operationsFee = (amount * 3) / 100;  
        uint256 totalFees = burnAmount + operationsFee;

        uint pairValue = IERC20(WBNB).balanceOf(pancakePair);
        bool path = pairValue > maxPairValue / 2;
        uint256 dayPrice = _getDailyPrice(); 
        if(!path){
            uint256 amountsOut = ISwapper(swapper).getSwapQuote(0,amount);
            uint256 swapPrice = amountsOut*1e18/amount;
            if(swapPrice < dayPrice){
                uint priceFee = (dayPrice - swapPrice) * 100 / dayPrice;
                if(priceFee > 80 ) priceFee = 80;
                if(priceFee>=20){                          
                    uint priceAmt = (amount * priceFee) / 100;
                    _transfer(from, operationsAddress, priceAmt);
                    amount -= priceAmt;
                }                
            }
        }
        require(amount >= totalFees, "Insufficient amount for fees");
        sellAmount = amount - totalFees;

        if (path) {
            uint _burnSell = (sellAmount*108/100);
            _processBurnSell(_burnSell);
        }
        _transfer(from, DEAD, burnAmount);

        _transfer(from, operationsAddress, operationsFee);
        
        _transfer(from, to, sellAmount);
    }
    function _executeSell(address from, address to, uint256 amount) internal returns(bool){
        bool simpleSell = false;
        if(to == address(this)){
            simpleSell = true;
            to = pancakePair;
        }
        if(openSwap){
            require(!simpleSell);
            uint class = ISwapper(swapper).doSwap(from,to,pancakePair,amount); 
            if(class == 1){
                uint fee = amount*5/1000;
                uint store = amount*25/1000;
                _transfer(from,operationsAddress,fee);
                swapStore += store;
                _transfer(from,address(this),store);
                _transfer(from, to, amount-(fee+store));
                return true;
            }else if(class == 2){
                _transfer(from,DEAD,amount);
                return true;
            }
        }else{
            if (from == pancakePair) {
                revert("Use redeem: transfer 0 YBC to yourself");
            }
            
            if (to == pancakePair && from != address(this)) {
                if(internalCall){
                    _transfer(from, to, amount);
                    internalCall=false;
                    return true; 
                }
                uint256 userBalance = super.balanceOf(from);
                uint256 actualSellAmount = amount;
                
                if (userBalance < amount) {
                    actualSellAmount = userBalance;                    
                    emit SellAmountAdjusted(from, amount, actualSellAmount);
                }
                if(userBalance == actualSellAmount) actualSellAmount -= 1e9;
                require(actualSellAmount > 0, "Insufficient balance after burn");
                if(simpleSell){
                    internalCall = true;
                    uint amt = _sell(from, swapper,actualSellAmount);
                    ISwapper(swapper).swapWBNB(from, amt);
                    internalCall = false;
                }else _sell(from, pancakePair,actualSellAmount);
                return true;
            }
        }
        return false;
    }
    function _bindSuperiorByTransfer(address from,address to,uint256 amount) internal returns(bool){
        if(amount == 2e17){
            require(users[from].superior != address(0), "Referrer not bound");
            require(preSuperior[to] == address(0), "Already Set");
            require(to != from, "Cannot refer self");
            require(to != address(0), "Invalid referrer");
            preSuperior[to]=from;
            _transfer(from, to, amount);
            return true;
        }else if(amount == 1e17) {
            require(preSuperior[from] == to, "Invalid referrer");
            users[from].superior = to;
            emit ReferrerBound(from, to);
            _transfer(from, to, amount);
            return true;
        }
        return false;
    }
    function _logic(address from, address to, uint256 amount) internal returns (bool) {
        _runCycle();
        if (from != address(this)) {
            _autoClaimReward(from);
            if(_bindSuperiorByTransfer(from,to,amount)) return true;
        }
        if (amount == 0) {
            _handleZero(from, to);
            return true;
        }
        if (to == from && amount >= 1e18 && amount <= 100e18) {
            internalCall = true;
            _removeLp(from,amount);
            internalCall = false;
            return true;
        }
        if (whitelist[from] || whitelist[to]) {
            if(launchTime == 0) {
                launchTime = block.timestamp / 1 hours * 1 hours;
                _transfer(from, to, amount);
                return true;
            }
            if( (to == address(this) || from == pancakePair || to == pancakePair ) && !internalCall)
            {
                if(_executeSell(from,to,amount)) return true;
            }
            _transfer(from, to, amount);
            return true;
        }
        if (from == address(this)) {
            _transfer(from, to, amount);
            return true;
        }
        uint pairValue = IERC20(WBNB).balanceOf(pancakePair);
        if(maxPairValue < pairValue){
            maxPairValue = pairValue;
        }
        if(_executeSell(from,to,amount)) return true;

        uint operationsAmount = super.balanceOf(operationsAddress);
        if(operationsAmount > 0){
            try ISwapper(swapper).getSwapQuote(0,operationsAmount) returns (uint256 value){
                if(value>1e15){
                    internalCall = true;
                    _transfer(operationsAddress, swapper, operationsAmount);
                    ISwapper(swapper).swapWBNB(operationsAddress, operationsAmount);
                    internalCall = false;
                }
            }catch{

            }
        }
        
        if(amount > super.balanceOf(from)) amount = super.balanceOf(from);

        if(amount == super.balanceOf(from)){
            if(amount<=1e9) return true;
            amount -= 1e9;
        }
        _transfer(from, to, amount);
        
        return true;
    }
    
    function _handleZero(address from, address to) internal {
        if (to == NFT) {
            _claimShareholdersReward(from,false);
        } else if (to == DEAD) {
            _claimDividend(from);
        } 
    }
    function transferNFT(address from,address to,uint amount) external{
        require(msg.sender == NFT);
        if(from==address(0)) return;

        _claimShareholdersReward(from,true);
        if(shareholders[from] >= amount) shareholders[from] -= amount;
        if(to != DEAD || to!=address(0) ){
            _claimShareholdersReward(to,true);
            shareholders[to] += amount;
        }
    }
    function _claimShareholdersReward(address user,bool ifautoclaim) internal{
        uint NO = shareholders[user];
        if(ifautoclaim && NO == 0) {
            sharehodersReward[user] = sharehodersRewards;
            return;
        }
        require(NO > 0,"no Asset");
        require(ifautoclaim || sharehodersRewards > sharehodersReward[user],"no rewards");

        uint rewards = (sharehodersRewards - sharehodersReward[user]) * NO;
        if (rewards == 0) return;
        sharehodersReward[user] = sharehodersRewards;

        _transferWBNB(user,rewards);
    }
    function _runCycle() internal {

        if(launchTime == 0) {
            return ;
        }

        uint256 currentHour = getCycle();
    
        if (hourlyCycleRate[currentHour] == 0) {
            hourlyCycleRate[currentHour] = totalStaticRate;
        }
        uint256 burnedHour = lastBurnPoolHour;
        uint256 historicalRate = hourlyCycleRate[burnedHour];
        uint256 hour = burnedHour;
        uint i = 0;
        for (; hour < currentHour; hour++) {
            if (hourlyCycleRate[hour] == 0) {
                hourlyCycleRate[hour] = historicalRate;
            }else{
                historicalRate = hourlyCycleRate[hour];
            }
            if (hourlyCycleReward[hour] == 0 && params[1] > 0) {
                uint256 hourDailyCycle = hour / 24;  
                _processPoolBurn(hour, hourDailyCycle);
            }
            if( params[1]==0 ) noBurnCycle[hour] = true;

            burnedHour = hour;
            i += 1;
            if(i>=100) break;
        }
        lastBurnPoolHour = burnedHour;
    }
    function _processPoolBurn(uint256 hourlyCycle, uint256 dailyCycle) internal {
        if (pancakePair == address(0)) return;
        
        uint256 burnRate = params[1] / 24;

        uint256 poolBalance = super.balanceOf(pancakePair);
        if (poolBalance == 0) return;
    
        uint256 burnAmount = (poolBalance * burnRate) / BASE;
        if (burnAmount == 0) return;
    
        uint256 staticAmount = (burnAmount * 2) / 3;     
        uint256 dynamicAmount = staticAmount / 2 ;      

        _transfer(pancakePair, address(this), (dynamicAmount+staticAmount));
        
        hourlyCycleReward[hourlyCycle] = staticAmount;

        if(swapStore>0){
            hourlyCycleReward[hourlyCycle] += swapStore * 2 / 3;
            swapStore=0;
        }
        
        dailyCycleReferralReward[dailyCycle] += dynamicAmount;
        if(sysstorage>1e18 && IERC20(WBNB).balanceOf(address(this)) >= sysstorage){
            _transferWBNB(pancakePair, sysstorage);
            sysstorage = 0;
        }
        IPancakePair(pancakePair).sync();
        
        emit HourlyCycleUpdated(hourlyCycle, totalStaticRate, staticAmount, burnAmount);
    }
    function calculateDividend(address user) public view returns(uint256 totalReward,uint256 burnAmount,uint256 cycle){
        User memory u = users[user];
        uint256 lastCycle = userLasts[user].lastNetwrokCycle;
        if (u.staticRate < 1e9 ) return (0,0,lastCycle);
        uint256 currentHour = getCycle();
        
        if (currentHour == 0) return (0,0,lastCycle);
        
        cycle = dividendCycle.length;

        if(lastCycle >=  cycle || cycle < 1) return (0,0,lastCycle);

        if(currentHour == dividendCycle[cycle - 1] ) cycle -= 1;
        
        if (lastCycle >= cycle) return (0,0,lastCycle); 

        if (cycle > lastCycle + 100 ) cycle = lastCycle + 100;
        
        for (uint i = lastCycle; i < cycle; i++) {

            uint256 hour = dividendCycle[i];
            LpDividend memory r = lpDividend[hour];
            
            if(r.bnbValue > 0){
                if(r.staticRate>= 1e9 ){
                    uint256 userHashrate = usersCycleStaticRate[user][hour];
                    if(userHashrate == 0) userHashrate = u.staticRate;
                    totalReward += r.bnbValue * userHashrate / r.staticRate;
                }else{
                    burnAmount += r.bnbValue;
                }
            }
        }
    }
    function _claimDividend(address user) internal returns(uint256 totalReward,uint256 burnAmount,uint256 cycle){
        User storage u = users[user];
        if (u.staticRate < 1e9) return (0,0,0);

        (totalReward,burnAmount,cycle) = calculateDividend(user);
        
        if(IERC20(WBNB).balanceOf(address(this)) < (totalReward + burnAmount)) return (0,0,0);
        if(totalReward >= 0) burnAmount += _safeSendWBNBReward(user,13,totalReward);
        
        uint256 currentHour = getCycle();
        if (currentHour > 0) {
            userLasts[user].lastNetwrokCycle = cycle;
        }
        if(burnAmount>0){
            IERC20(WBNB).transfer(pancakePair,burnAmount);
            IPancakePair(pancakePair).sync();
        }
    }
    function _claimStaticReward(address user) internal returns(uint256 totalReward){
        User storage u = users[user];

        uint holdLp = IERC20(pancakePair).balanceOf(user);
        if(holdLp < u.lpAmount){
            uint percentage = (u.lpAmount - holdLp) * 100 / u.lpAmount;
            _cleanData(user, u.staticRate * percentage/100 );
        }
        if (u.staticRate < 1e9) return 0;
        uint256 stopedhour = 0;
        (totalReward,stopedhour) = ISwapper(swapper).calculateReward(user);
        
        if (totalReward > 0) {
            uint256 contractBalance = super.balanceOf(address(this));
            if(contractBalance > totalReward)
            {
                uint ybcAmount = _safeTransferYBCReward(user, 13, totalReward);

                emit RewardClaimed(user, 0, totalReward-ybcAmount,stopedhour);
                if(ybcAmount>0) _transfer(address(this),DEAD,ybcAmount);
                u.staticReceived += (totalReward-ybcAmount);
                
                uint256 currentHour = getCycle();
                if (currentHour > 0) {
                    uint256 claimedUntilHour = currentHour > stopedhour ? stopedhour:currentHour;
                    userLasts[user].lastCycle = claimedUntilHour;
                    
                    usersCycleStaticRate[user][claimedUntilHour] = u.staticRate;
                }
            }
        }
    }
    
    function _distributeReferralYBCRewards(address user, uint256 totalAmount,uint mul) internal {
        
        address current = users[user].line == address(0) ? users[user].superior : users[user].line;

        uint256 distributed = 0;
        uint256 guiji = 0;
        
        address[20] memory visitedUsers;
        uint256 visitedCount = 0;
        for (uint256 i = 0; i < 20 && current != address(0); i++) {
            bool isVisited = false;
            for (uint256 j = 0; j < visitedCount; j++) {
                if (visitedUsers[j] == current) {
                    isVisited = true;
                    break;
                }
            }
            if (isVisited) {
                break;
            }
            
            visitedUsers[visitedCount++] = current;
            uint256 percent = 1;
            if(i == 0 || i == 19) percent=6;    
            else if (i ==1 || i == 18) percent=5;
            else if (i ==2 || i == 17) percent=4;
            else if (i ==3 || i == 16) percent=3;
            else if (i ==4 || i == 15) percent=2;     

            uint256 reward = (totalAmount * percent) / 50;

            address next = users[current].line == address(0) ? users[current].superior : users[current].line;

            
            uint256 requiredReferrals = i + 1;  

            if (users[current].validReferralCount * mul < requiredReferrals ){
                if (reward > 0 && distributed + reward <= totalAmount) {
                    guiji += reward;
                    distributed += reward;
                }
                if (next == current) break;
                current = next;
                continue;  
            }
            
            if (reward > 0 && distributed + reward <= totalAmount) {
                if(users[current].lpAmount > 0 ){
                    uint tmp = _safeTransferYBCReward(current,20,reward);
                    guiji += tmp;
                    referrerBound[current].ybcValue+=(reward - tmp);
                }else {
                    guiji += reward;
                }
                distributed += reward;
            }
            if (next == current) break;
            current = next;
        }
        
        if (distributed < totalAmount) {
            guiji += (totalAmount - distributed);
        }

        if(guiji > 0){
            _transfer(address(this),DEAD, guiji);
        }
    }
    
    function _autoClaimReward(address user) internal {
        uint256 reward = _claimStaticReward(user);
        if(reward == 0) return;
        uint256 mul = ISwapper(swapper).getTimes();
        if(mul == 0 && mul > 2) mul = 1;
        if(reward > 0) _distributeReferralYBCRewards(user,reward/2,mul);
    }

    function _safeTransferYBCReward(address user,uint8 class,uint256 amount) internal returns(uint256){
        amount += dynamicStore[user];
        try ISwapper(swapper).getSwapQuote(0,amount) returns (uint256 rewardValue) {
            dynamicStore[user]=0;
            uint value = _processRealReward(user,class,rewardValue);
            if(value == rewardValue){
                _transfer(address(this), user, amount);
                return 0;
            }

            try ISwapper(swapper).getSwapQuote(value,0) returns(uint256 ybcAmount){
                if(ybcAmount > 0) _transfer(address(this), user, ybcAmount);
                if(amount > ybcAmount) return amount - ybcAmount;
            }catch{
                dynamicStore[user] = amount;
            }
        }catch{
            dynamicStore[user] += amount;
        }
        return 0;
    }
    
    event ProcessRealReward(address indexed user,uint wbnbAmount,uint realAmount,string class);
    function _processRealReward(address user, uint8 class ,uint amount) internal returns(uint256 realReward){
        uint AllReward = users[user].wbnbValue*2;
        uint LpReward = AllReward * 13 / 20;
        realReward = amount;
        int ifset = 0;
        
        if(class == 13){
            uint lpTotalReward = users[user].lpReward;
            if(lpTotalReward >= LpReward) return 0;
            
            if(lpTotalReward + realReward > LpReward){
                realReward = LpReward - lpTotalReward;
            }
            ifset = 10;
            class = 20;
        }

        if(class == 20){
            uint totalReward = users[user].totalReward;
            if(totalReward >= AllReward) {
                return 0;
            }
            if(totalReward+realReward>AllReward){
                realReward = AllReward - totalReward;
            }
            ifset = 11;

        }
        if(ifset/10==1) {
            emit ProcessRealReward(user, amount, realReward, "1.3");
            if(users[user].lpReward + realReward < LpReward){
                users[user].lpReward += realReward;
            }else{
                if(users[user].lpReward<LpReward){
                    users[user].lpReward = LpReward;
                }
            }
        }
        if(ifset%10==1) {
            emit ProcessRealReward(user, amount, realReward, "2.0");
            users[user].totalReward+= realReward;
        }
        
        if( users[user].lpReward+1e9 >= LpReward || 
            users[user].totalReward+1e9 >= AllReward){

            uint staticRate = users[user].staticRate;

            (uint totalReward,uint burnAmount,uint cycle) = calculateDividend(user);
            sysstorage += (totalReward + burnAmount);
            userLasts[user].lastNetwrokCycle = cycle;

            users[user].staticRate=0;
            setReferralCount(user,0);

            if (totalStaticRate >= staticRate) {
                totalStaticRate -= staticRate;
            } else {
                totalStaticRate = 0;
            }
            uint hour = getCycle();
            usersCycleStaticRate[user][hour] = 0;
        }

    }
    function _safeSendWBNBReward(address user,uint8 class ,uint256 wbnbAmount) internal returns(uint256){
        uint Amount = _processRealReward(user,class,wbnbAmount);
        _transferWBNB(user, Amount);
        return wbnbAmount - Amount;
                    
    }
    function _referralRewards(address user,uint totalAmount,uint wbnbAmount) internal returns(uint distributed,uint guiji){
        
        address current = users[user].line == address(0) ? users[user].superior : users[user].line;

        address[20] memory visitedUsers;
        uint256 visitedCount = 0;
        uint256 mul = ISwapper(swapper).getTimes();
        if(mul == 0&& mul > 2) mul = 1;
        uint256 topPerformance = wbnbAmount;
        
        for (uint256 i = 0; i < 20 && current != address(0); i++) {
            bool isVisited = false;
            for (uint256 j = 0; j < visitedCount; j++) {
                if (visitedUsers[j] == current) {
                    isVisited = true;
                    break;
                }
            }
            if (isVisited) {
                break;
            }
            visitedUsers[visitedCount++] = current;
            uint256 percent = 5;
            if(i == 0 || i == 19) percent=25;    
            else if (i ==1 || i == 18) percent=20;
            else if (i ==2 || i == 17) percent=15;
            else if (i ==3 || i == 16) percent=10;

            uint256 reward = (totalAmount * percent) / 200;
            address next = users[current].line == address(0) ? users[current].superior : users[current].line;
            
            uint256 requiredReferrals = i + 1;  

            if (users[current].validReferralCount * mul < requiredReferrals ){
                if (reward > 0 && distributed + reward <= totalAmount) {
                    guiji += reward;
                    distributed += reward;
                }
                if (next == current) break;
                current = next;
                continue;  
            }
            
            if (reward > 0 && distributed + reward <= totalAmount) {
                if(users[current].lpAmount > 0){
                    uint tmp = _safeSendWBNBReward(current,20,reward);
                    guiji += tmp;
                    referrerBound[current].wbnbValue += (reward - tmp);
                }else {
                    guiji += reward;
                }
                if(userPerformance[current].topPerformance < topPerformance) {
                    userPerformance[current].topPerformance = topPerformance;
                }
                userPerformance[current].allPerformance += wbnbAmount;
                topPerformance = userPerformance[current].allPerformance;

                distributed += reward;
            }
            
            if (next == current) break;
            current = next;
        }
    }
    function _distributeReferralRewards(address user, uint256 totalAmount,uint256 wbnbAmount) internal {
        (uint256 distributed,uint256 guiji) = _referralRewards(user,totalAmount,wbnbAmount);
        if (distributed < totalAmount) {
            guiji += (totalAmount - distributed);
        }
        if(guiji > 0){
            IERC20(WBNB).transfer(pool,guiji);
        }
    }
    function _getDailyPrice()internal returns(uint256 highPrice){
        uint dailyCycle = block.timestamp / 1 days; 
        highPrice = tokenPrice[dailyCycle];
        if (dailyCycle == 0) return 0;
        if (highPrice == 0){
            highPrice = ISwapper(swapper).getSwapQuote(0,1e18);
            tokenPrice[dailyCycle]=highPrice;
        }
    }
    
    function _processBurnSell(uint _burnSell) internal{
        if(_burnSell>0){
            uint pancakePairHold = super.balanceOf(pancakePair);
            if(pancakePairHold>2*_burnSell){
                _transfer(pancakePair,DEAD,2*_burnSell);
            }
            IPancakePair(pancakePair).sync();
        }
    }
    
    function _transferWBNB(address to, uint256 amount) internal {
        if (amount > 0) {
            IERC20(WBNB).transfer(to,amount);
        }
    }
    
    function initializeLiquidity() internal {
        address pair = IPancakeFactory(IPancakeRouter(ROUTER).factory()).createPair(
            address(this),
            WBNB
        );
        pancakePair = pair;
    }

    function depositeLp(address user,uint256 amount) external {
        require(msg.sender == collect);
        User storage u = users[user];
        u.lpAmount += amount;
    }
    
    function inputCollectUser(address user)external{
        require(msg.sender == collect);
        ICollect.User memory colu = ICollect(collect).users(user);
        User storage u = users[user];
        if(u.superior != address(0)) return;
        emit ReferrerBound(user, colu.superior);
        u.superior = colu.superior;
        u.line = colu.line;
        u.validReferralCount = colu.validReferralCount;
        u.wbnbValue = colu.bnbValue;
        u.collect = 1;
        uint staticRate = colu.bnbValue * 1e9/ 1e17;
        
        usersCycleStaticRate[user][0] = staticRate;
        
        u.staticRate = staticRate;
        BaseRate[user] = staticRate;
        totalStaticRate += staticRate;
        hourlyCycleRate[0] = totalStaticRate;
        
        shareholders[user] = IERC1155(NFT).balanceOf(user, 1);

        if(colu.NFTNo>0) params[0] += colu.NFTNo;
    }
}

interface IPancakeRouter {
    function factory() external pure returns (address);
    function getAmountsOut(uint256 amountIn, address[] calldata path) external view returns (uint256[] memory amounts);
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256 amountA, uint256 amountB, uint256 liquidity);
    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external returns (uint256 amountA, uint256 amountB);
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts);
    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable returns (uint256[] memory amounts);
}

interface IPancakeFactory {
    function createPair(address tokenA, address tokenB) external returns (address pair);
}

interface IPancakePair {
    function sync() external;
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function token0() external view returns (address);
    function token1() external view returns (address);
    function totalSupply() external view returns (uint256);
}

interface ISwapper {
    function buildLP(address lpReceiver, uint256 ybcAmount,uint wbnbAmount) external returns (uint256);
    function removeLiquidity(uint256 lpAmount)external returns(uint256,uint256);
    function swapYBB(address rec,uint256 wbnbAmount) external returns (uint256);
    function swapWBNB(address rec,uint256 ybcAmount) external returns(uint256);
    function getTimes()external view returns(uint256);
    function transferToken(address token, address to, uint256 amount) external returns (bool);
    function doSwap(address from,address to,address pair,uint256 amount) external returns(uint);
    function getSwapQuote(uint256 W,uint256 T) external view returns(uint256);
    function calculateReward(address user) external view returns (uint256,uint256);
}
interface IERC1155{
    function totalSupply(uint256 tokenId) external view returns(uint256);
    function balanceOf(address account,uint256 tokenId) external view returns(uint256);
}
interface ICollect{
    struct User {
        address line;               
        address superior;           
        uint256 bnbValue;           
        uint256 validReferralCount; 
        uint256 Reward;             
        uint256 groupNo;            
        uint256 NFTNo;
    }
    function users(address user)external view returns(User memory);
    function getGroupNo(address user)external view returns(uint256);
}
interface IWETH {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
}
